#!/usr/bin/env python3
"""Generate MAPPINGS.md from the packs and the Sigma/YARA rules.

  python artifacts/scripts/mappings.py          # write MAPPINGS.md
  python artifacts/scripts/mappings.py --check  # CI: fail if MAPPINGS.md is stale

Hand-maintained mapping tables drift. This one cannot, because CI regenerates
it and compares.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "MAPPINGS.md"


def build() -> str:
    L = ["# Mappings", "",
         "Generated by `artifacts/scripts/mappings.py`. Do not edit by hand.", "",
         "## Detection packs", "",
         "| Pack | Detection | Tier | Evidence class | CVEs | ATT&CK |",
         "|---|---|---|---|---|---|"]
    for p in sorted((ROOT / "artifacts" / "packs").glob("*.yml")):
        pack = yaml.safe_load(p.read_text())
        for d in pack["detect"]:
            L.append(f"| {pack['id']} | `{d['id']}` | {d['tier']} | {d['evidence_class']} | "
                     f"{', '.join(pack.get('cves', [])) or '-'} | {', '.join(d.get('attack', [])) or '-'} |")
    L += ["", "## Rules", "", "| File | Format | CVEs | ATT&CK |", "|---|---|---|---|"]
    for f in sorted(list(ROOT.glob("[0-9][0-9]-*/*.yml")) + list(ROOT.glob("[0-9][0-9]-*/*.yar"))):
        text = f.read_text()
        rel = f.relative_to(ROOT).as_posix()
        if f.suffix == ".yml":
            tags = yaml.safe_load(text).get("tags", [])
            cves = sorted({t.replace("cve.", "CVE-").upper() for t in tags if t.startswith("cve.")})
            att = sorted({t.split(".", 1)[1].upper() for t in tags if re.match(r"attack\.t\d{4}", t)})
            L.append(f"| `{rel}` | Sigma | {', '.join(cves) or '-'} | {', '.join(att) or '-'} |")
        else:
            cves = sorted(set(re.findall(r'cve = "(CVE-\d{4}-\d+)"', text)))
            L.append(f"| `{rel}` | YARA | {', '.join(cves) or '-'} | - |")
    return "\n".join(L) + "\n"


def main() -> int:
    content = build()
    if "--check" in sys.argv:
        if not OUT.exists() or OUT.read_text() != content:
            print("MAPPINGS.md is stale: run python artifacts/scripts/mappings.py")
            return 1
        print("MAPPINGS.md is current")
        return 0
    OUT.write_text(content)
    print(f"wrote {OUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
